"""Scoped API credentials and local operations; no second identity or job queue."""
from sqlalchemy import Column,Text,Integer,BigInteger,Boolean,DateTime,ForeignKey,ForeignKeyConstraint,CheckConstraint,UniqueConstraint,Index
from sqlalchemy.dialects.postgresql import UUID,JSONB

SERVICE_OPERATIONS_IMMUTABLE=("service_configuration_versions","service_announcements","service_requests","service_request_events","service_export_files","service_api_calls","service_api_call_jobs")

def declare_service_operations(project_table,ref,uid,stamp):
    def identity(name):return Column(name,UUID(as_uuid=False),ForeignKey('access_identities.id',ondelete='RESTRICT'),nullable=False)
    configs=project_table('service_configuration_versions',Column('version',Integer,nullable=False),Column('document',JSONB,nullable=False),Column('sha256',Text,nullable=False),identity('created_by'),stamp(),UniqueConstraint('project_id','version'),CheckConstraint('version>0',name='version'))
    announcements=project_table('service_announcements',Column('announcement_key',Text,nullable=False),Column('version',Integer,nullable=False),Column('title',Text,nullable=False),Column('body',Text,nullable=False),Column('status',Text,nullable=False),identity('created_by'),stamp(),UniqueConstraint('project_id','announcement_key','version'),CheckConstraint("status IN ('published','withdrawn') AND version>0",name='status'))
    requests=project_table('service_requests',identity('requester_id'),Column('kind',Text,nullable=False),Column('title',Text,nullable=False),Column('body',Text,nullable=False),Column('contact',Text,nullable=False),Column('channel',Text,nullable=False),*ref('artifact_versions','artifact_id',nullable=True),*ref('media_items','media_id',nullable=True),Column('requested_fields',JSONB,nullable=False),Column('feedback_category',Text),stamp(),UniqueConstraint('project_id','id','requester_id'),CheckConstraint("feedback_category IS NULL OR (kind='feedback' AND feedback_category IN ('feature','quality','billing','ux','bug'))",name='feedback_category'),CheckConstraint("kind IN ('feedback','support','fcp','studio','production_service','distribution','account_close','personal_export')",name='kind'))
    events=project_table('service_request_events',*ref('service_requests','request_id'),Column('sequence',Integer,nullable=False),Column('status',Text,nullable=False),Column('reason',Text,nullable=False),identity('created_by'),stamp(),UniqueConstraint('project_id','request_id','sequence'),CheckConstraint("status IN ('received','under_review','awaiting_configuration','local_approved','rejected','withdrawn','export_ready','error','account_closed') AND sequence>0",name='status'))
    exports=project_table('service_export_files',*ref('service_requests','request_id'),identity('requester_id'),Column('snapshot_revision',BigInteger,nullable=False),Column('snapshot',JSONB,nullable=False),Column('snapshot_sha256',Text,nullable=False),Column('object_key',Text,nullable=False),Column('sha256',Text,nullable=False),Column('size_bytes',BigInteger,nullable=False),Column('expires_at',DateTime(timezone=True),nullable=False),stamp(),UniqueConstraint('project_id','request_id'),ForeignKeyConstraint(['project_id','request_id','requester_id'],['service_requests.project_id','service_requests.id','service_requests.requester_id']),CheckConstraint('snapshot_revision>=0 AND size_bytes>0',name='size'))
    keys=project_table('service_api_keys',identity('identity_id'),Column('name',Text,nullable=False),Column('secret_sha256',Text,nullable=False,unique=True),Column('prefix',Text,nullable=False),Column('ip_allowlist',JSONB,nullable=False,server_default='[]'),Column('requests_per_minute',Integer,nullable=False,server_default='0'),CheckConstraint("jsonb_typeof(ip_allowlist)='array' AND requests_per_minute BETWEEN 0 AND 10000",name='network_limits'),Column('capabilities',JSONB,nullable=False),Column('expires_at',DateTime(timezone=True),nullable=False),Column('revoked',Boolean,nullable=False,server_default='false'),stamp(),UniqueConstraint('id'),CheckConstraint("jsonb_typeof(capabilities)='array' AND capabilities <@ '[\"read\",\"execute\"]'::jsonb AND capabilities @> '[\"read\"]'::jsonb",name='capabilities'))
    calls=project_table('service_api_calls',*ref('service_api_keys','api_key_id'),Column('call_id',UUID(as_uuid=False),nullable=False),Column('phase',Text,nullable=False),Column('operation',Text,nullable=False),Column('status_code',Integer,nullable=False),Column('error_code',Text),*ref('artifact_versions','run_version_id',nullable=True),stamp(),UniqueConstraint('project_id','call_id','phase'),CheckConstraint("phase IN ('started','finished') AND status_code BETWEEN 0 AND 599",name='phase'))
    call_jobs=project_table('service_api_call_jobs',*ref('service_api_calls','call_event_id'),*ref('generation_jobs','job_id'),UniqueConstraint('project_id','call_event_id','job_id'))
    Index('ix_service_requests_feedback_owner',requests.c.project_id,requests.c.requester_id,requests.c.kind,requests.c.created_at,requests.c.id)
    Index('ix_service_requests_feedback_manage',requests.c.project_id,requests.c.kind,requests.c.created_at,requests.c.id)
    tables=(configs,announcements,requests,events,exports,keys,calls,call_jobs)
    for table in tables:
        for col in table.c:
            if col.name.endswith('_id') and col.name not in {'id','project_id'}:Index('ix_'+table.name+'_'+col.name,table.c.project_id,col)
    return {table.name:table for table in tables}
